    if len(v) <= 1 {
        return v
    }

    let pivot = get(v, 0)?
    let mut less = vec()
    let mut greater = vec()

    for x in v {
        if x < pivot {
            less = push(less, x)
        } else {
            greater = push(greater, x)
        }
    }

    let mut sorted = sort(less)
    sorted = push(sorted, pivot)
    sorted = append(sorted, sort(greater))
    return sorted
}

